<script setup>
import { computed } from 'vue';
const props = defineProps({ history: { type: Object, required: true } });
defineEmits(['close','refresh']);
const date = value => value ? new Date(value).toLocaleString([], { dateStyle: 'medium', timeStyle: 'medium' }) : 'Not recorded';
const action = log => log.dispatchType === 'poll_followup' || log.dispatchType?.startsWith('reminder_') ? (log.occurrenceKey?.startsWith('manual:') ? 'Manual follow-up' : 'Scheduled follow-up') : log.dispatchType === 'vote_invite' ? 'Poll invitation' : log.dispatchType === 'poll_results' ? 'Final results' : 'Event message';
const channel = value => ({ in_app: 'In app', sms: 'Text', email: 'Email' })[value] || value;
const status = log => log.channel === 'in_app' && log.status === 'sent' ? 'Available in app' : log.channel === 'sms' && log.status === 'sent' ? 'Sent · awaiting delivery receipt' : ({ sent: 'Sent', delivered: 'Delivered', failed: 'Failed', skipped: 'Skipped', queued: 'Queued' })[log.status] || log.status;
const people = computed(() => props.history.recipients || []);
</script>
<template>
  <section class="delivery-history" aria-label="Team delivery history">
    <header><h3>{{ history.title }} · delivery history</h3><div><button type="button" @click="$emit('refresh')">Refresh history</button><button type="button" @click="$emit('close')">Close history</button></div></header>
    <p class="hint">Times are shown in your local time. A text delivery receipt confirms delivery, not that the person read it. App views are recorded when the poll is visible; older views may not have been recorded.</p>
    <div v-if="people.length" class="people"><article v-for="person in people" :key="person.userId"><strong>{{ person.name }}</strong><span class="status" :class="person.status">{{ person.status === 'answered' ? 'Answered' : person.status === 'awaiting_reply' ? 'Awaiting reply' : 'Not sent' }}</span><p>{{ person.explanation }}</p><dl><template v-if="person.answeredAt"><dt>Responded {{ person.responseSource === 'sms' ? 'by text' : 'in app' }}</dt><dd>{{ date(person.answeredAt) }}</dd></template><dt>Last viewed in app</dt><dd>{{ date(person.lastViewedAt) }}</dd></dl></article></div>
    <h4>Messages and follow-ups</h4><p v-if="!history.logs?.length">No messages have been sent yet. Responses made directly in the app appear above.</p>
    <ol class="timeline"><li v-for="log in history.logs" :key="log.id"><div class="line"><strong>{{ log.name }}</strong><span>{{ channel(log.channel) }} · {{ action(log) }}</span><span class="status" :class="log.status">{{ status(log) }}</span></div><p v-if="log.statusReason">{{ log.statusReason }}</p><dl><dt>{{ log.sentAt ? 'Sent' : 'Recorded' }}</dt><dd>{{ date(log.sentAt || log.createdAt) }}</dd><template v-if="log.channel === 'sms'"><dt>Delivery confirmed</dt><dd>{{ date(log.deliveredAt) }}</dd></template><template v-if="log.channel === 'in_app'"><dt>Poll viewed after this message</dt><dd>{{ date(log.viewedAt) }}</dd></template><template v-if="log.failedAt"><dt>Failed</dt><dd>{{ date(log.failedAt) }}</dd></template></dl></li></ol>
  </section>
</template>
<style scoped>
.delivery-history{background:#fff;border:1px solid #dce5f0;border-radius:16px;padding:20px;margin-top:20px;color:#152c50}.delivery-history header,.line{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between}.delivery-history h3{margin:0}.delivery-history button{padding:8px 12px;border:1px solid #b8c8df;border-radius:8px;background:white;color:#245ccb;cursor:pointer;margin:3px}.hint,.delivery-history p{font-size:12px;color:#53647c;line-height:1.6}.people{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}.people article,.timeline li{padding:14px;border:1px solid #dce5f0;border-radius:10px}.people article{background:#f8faff}.status{font-size:11px;background:#edf2fa;border-radius:20px;padding:4px 8px;display:inline-block}.answered,.delivered{background:#e5f4ed;color:#176447}.not_sent,.skipped,.queued{background:#fff3db;color:#80510b}.failed{background:#fef2f2;color:#9b2525}.people .status{margin-left:8px}.timeline{list-style:none;padding:0;display:grid;gap:10px}.line>span:not(.status){font-size:12px;color:#53647c}.delivery-history dl{display:grid;grid-template-columns:1fr 1fr;gap:4px 12px;margin:10px 0 0;font-size:12px}.delivery-history dt{color:#53647c}.delivery-history dd{margin:0;overflow-wrap:anywhere}.delivery-history button:focus-visible{outline:3px solid #83b5ff}@media(max-width:500px){.delivery-history{padding:14px}.people{grid-template-columns:1fr}.delivery-history dl{grid-template-columns:1fr}.delivery-history dd{margin-bottom:6px}}
</style>
